mapper.select:
select t1.id, t1.product_name, t1.bandwidth, t1.network_count, t1.ip_count, t1.actual_status, t1.pay_status, t1.original_amount as originalAmount, t4.customer_name as userName, t4.phone, t2.pay_time, t2.final_pay_amount as payAmount, t1.create_time, t1.actual_agi_open_time, t1.actual_agi_expire_time, t1.charge_type, t1.duration, t1.duration_unit, t3.image as productImg, t3.refer_price, t3.crossed_price, t1.remark, t1.agi_customer_name, t1.mobile from sys_network_value t1 left join sys_order t2 on t1.id = t2.network_value_id left join sys_network_product t3 on t1.product_id = t3.id left join sys_customer t4 on t1.user_id = t4.id
and t1.product_name like concat('%',#{param.productName},'%')
and t4.customer_name like concat('%',#{param.nickname},'%')
and t4.phone like concat('%',#{param.mobile},'%')
and t1.actual_agi_open_time >= #{param.startTime}
and t1.actual_agi_open_time <= #{param.endTime}
and t1.pay_status = #{param.payStatus}
and t2.final_pay_amount = #{param.payPrice}
and t1.actual_status = #{param.actualStatus}
and t1.mobile like concat('%',#{param.customerMobile},'%')
and t1.agi_customer_name like concat('%',#{param.customerName},'%')
and t1.email like concat('%',#{param.email},'%')
order by t1.create_time desc
